export const JUNGLE_REGISTRATION=Object.freeze({pointId:'event:S5_JUNGLE_DOME_EXPEDITION',eventId:'S5_JUNGLE_DOME_EXPEDITION',rewardId:'TX_S5_JUNGLE_DOME_REWARD',mapId:'world:area:S5_GEOJE_JUNGLE_DOME',sceneId:'jungle-interior-r2',ruleRevision:RULE_REVISION,imageSHA:'63efd7734157575a4e0105263747827037329c3860fdfa620a19a0bb4c444e34',maskSHA:'5990e5bcc959a626c3ab4abaa8e1476f582d609c51c878fab5d0b09157c33924',symbolSHA:APPROVED_SYMBOL_SELECTION.layerSHA256});
const R=JUNGLE_REGISTRATION,owners=new WeakMap(),grants=new WeakMap(),consumed=new WeakSet(),reserved=new WeakMap();
// Only the live session owner may construct this dependency. No DTO or exported receipt can reconstruct it.
export function createJungleAuthority({readNative,readCompletion,supports}={}){if(typeof readNative!=='function'||typeof readCompletion!=='function'||typeof supports!=='function')throw Error('JUNGLE_LIVE_OWNER_REQUIRED');const a=Object.freeze({});owners.set(a,{readNative,readCompletion,supports});return a}
function completion(o){return dataRecord(o.readCompletion(),['controller','receipt'])}
export const isJungleAuthority=a=>owners.has(a);
export function isJungleRequest(id,a){const d=dataRecord(a,['type']);return id===R.pointId&&d?.type==='event'}
const nativeKeys=['sceneId','mapId','ruleRevision','imageSHA','maskSHA','symbolSHA','pinsVerified','foot','facing','layer','interiorState','phase','sessionEpoch'];
function read(o){const n=dataRecord(o.readNative(),nativeKeys);if(!n||n.sceneId!==R.sceneId||n.mapId!==R.mapId||n.ruleRevision!==R.ruleRevision||n.imageSHA!==R.imageSHA||n.maskSHA!==R.maskSHA||n.symbolSHA!==R.symbolSHA||n.pinsVerified!==true||n.facing!=='up'||n.layer!=='ground'||n.interiorState!=='OPEN'||n.phase!=='field'||!Number.isSafeInteger(n.sessionEpoch)||n.sessionEpoch<0)return null;const f=n.foot;if(!Array.isArray(f)||Reflect.ownKeys(f).length!==3)return null;const x=Object.getOwnPropertyDescriptor(f,'0'),y=Object.getOwnPropertyDescriptor(f,'1');if(!x||!y||!x.enumerable||!y.enumerable||Object.getOwnPropertyDescriptor(f,'length').value!==2||!Object.hasOwn(x,'value')||!Object.hasOwn(y,'value')||!isExhibitApproach([x.value,y.value],n.facing,n.interiorState,n.layer)||o.supports(['ground'],[x.value,y.value],'OPEN')!==true)return null;return n}
function canonical(w){const s=w.snapshot(),p=w.definition.points[R.pointId],e=w.story.contract.events[R.eventId],r=w.story.contract.rewards[R.rewardId];return s.position.scene===R.mapId&&s.world?.mapId===R.mapId&&p?.id===R.pointId&&p.kind==='event'&&p.mapId===R.mapId&&p.stageId==='S5'&&p.areaId==='S5_GEOJE_JUNGLE_DOME'&&p.x===5&&p.y===11&&p.eventId===R.eventId&&p.npcId===null&&p.gate==null&&w.definition.eventBindings[R.eventId]===R.pointId&&e?.active===true&&JSON.stringify(e.requiresEvents)==='["S5_FOOD_WEB_REVEAL"]'&&JSON.stringify(e.requiresGates)==='[]'&&r?.id===R.rewardId&&r.triggerEvent===R.eventId&&r.trigger_event===R.eventId&&r.atomic===true&&JSON.stringify(r.requires)==='["!S5_JUNGLE_DOME_COMPLETE"]'&&JSON.stringify(r.grant)==='{"plant_scan_module":1}'&&JSON.stringify(r.set_flags)==='["S5_JUNGLE_DOME_COMPLETE"]'&&s.progress.completedEvents.includes('S5_FOOD_WEB_REVEAL')&&!s.progress.completedEvents.includes(R.eventId)&&!s.progress.rewardClaims.includes(R.rewardId)&&s.progress.flags.S5_JUNGLE_DOME_COMPLETE!==true&&w.story.eventAvailable(R.eventId)}
export function mintJungleGrant(a,w,id){const o=owners.get(a),p=o&&completion(o);if(!o||!p||id!==R.pointId||consumed.has(p.receipt)||reserved.has(p.receipt)||!verifyCompletionProof(p.receipt,p.controller,w)||!canonical(w))throw Error('JUNGLE_AUTHORITY_REJECTED');const n=read(o);if(!n)throw Error('JUNGLE_AUTHORITY_REJECTED');const g=Object.freeze({});grants.set(g,{a,w,epoch:n.sessionEpoch,receipt:p.receipt,controller:p.controller,beforeItems:w.snapshot().progress.items.plant_scan_module??0,status:'live'});reserved.set(p.receipt,g);return g}
export function validateJungleGrant(g,w){const q=grants.get(g),o=q&&owners.get(q.a),p=o&&completion(o);if(!q||q.w!==w||q.status!=='live'||!p||p.receipt!==q.receipt||p.controller!==q.controller||consumed.has(q.receipt)||!verifyCompletionProof(q.receipt,q.controller,w)||!canonical(w))return false;const n=read(o);return !!n&&n.sessionEpoch===q.epoch}
