export function markJunglePending(g){const q=grants.get(g);if(q)q.status='pending'}
// Commit acknowledgement, not issuance of rewards. Retry remains story.retryCommit(), never runEvent again.
export function acknowledgeJungleCommit(g,w){const q=grants.get(g);if(!q||q.w!==w||!['live','pending'].includes(q.status)||w.story.pendingCommit)return false;const s=w.snapshot();if(!s.progress.completedEvents.includes(R.eventId)||!s.progress.rewardClaims.includes(R.rewardId)||s.progress.flags.S5_JUNGLE_DOME_COMPLETE!==true||s.progress.items.plant_scan_module!==q.beforeItems+1)return false;consumed.add(q.receipt);q.status='consumed';return true}
export function revokeJungleGrant(g){const q=grants.get(g);if(q&&reserved.get(q.receipt)===g)reserved.delete(q.receipt);grants.delete(g)}

function verifyCompletionProof(receipt,controller,world){return verifyLocalReceipt(receipt,controller)||verifyDurableReceipt(receipt,controller,world)}
